import java.util.*;
import java.io.*;

public class Main {
    // Return the board of step numbers, or an empty array if no tour exists.
    static int[][] knightsTour(int n, int r, int c) {
        // Write your solution here
        return new int[0][0];
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), r = sc.nextInt(), c = sc.nextInt();
        int[][] board = knightsTour(n, r, c);
        if (board.length == 0) {
            System.out.println(-1);
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int[] row : board) {
            for (int j = 0; j < row.length; j++) sb.append(row[j]).append(j + 1 < row.length ? " " : "\n");
        }
        System.out.print(sb);
    }
}
